CREATE TABLE IF NOT EXISTS app_user (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, username VARCHAR(64) NOT NULL UNIQUE CHECK (char_length(btrim(username)) >= 3), password_hash VARCHAR(255) NOT NULL CHECK (password_hash <> ''), created_at TIMESTAMP NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS coordinates (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (id > 0), x DOUBLE PRECISION NOT NULL, y REAL NOT NULL, version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS magic_city (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (id > 0), name VARCHAR(255) NOT NULL CHECK (btrim(name) <> ''), area DOUBLE PRECISION NOT NULL CHECK (area > 0), population BIGINT NOT NULL CHECK (population > 0), establishment_date DATE, governor VARCHAR(16) NOT NULL CHECK (governor IN ('HOBBIT', 'ELF', 'HUMAN', 'GOLLUM')), capital BOOLEAN NOT NULL, population_density INTEGER CHECK (population_density > 0), version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS ring (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (id > 0), name VARCHAR(255) NOT NULL CHECK (btrim(name) <> ''), weight INTEGER NOT NULL CHECK (weight > 0), version BIGINT NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS book_creature (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK (id > 0), name VARCHAR(255) NOT NULL CHECK (btrim(name) <> ''), coordinates_id BIGINT NOT NULL REFERENCES coordinates (id) ON DELETE CASCADE, creation_date TIMESTAMP NOT NULL DEFAULT now(), age INTEGER NOT NULL CHECK (age > 0), creature_type VARCHAR(16) NOT NULL CHECK (creature_type IN ('HOBBIT', 'ELF', 'HUMAN', 'GOLLUM')), creature_location_id BIGINT NOT NULL REFERENCES magic_city (id) ON DELETE CASCADE, attack_level INTEGER CHECK (attack_level > 0), defense_level REAL CHECK (defense_level > 0), ring_id BIGINT REFERENCES ring (id) ON DELETE SET NULL, version BIGINT NOT NULL DEFAULT 1, CONSTRAINT book_creature_ring_unique UNIQUE (ring_id) DEFERRABLE INITIALLY DEFERRED);
ALTER TABLE coordinates ADD COLUMN IF NOT EXISTS version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE magic_city ADD COLUMN IF NOT EXISTS version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE ring ADD COLUMN IF NOT EXISTS version BIGINT NOT NULL DEFAULT 0;
ALTER TABLE book_creature ADD COLUMN IF NOT EXISTS version BIGINT NOT NULL DEFAULT 1;
CREATE INDEX IF NOT EXISTS book_creature_coordinates_idx ON book_creature (coordinates_id);
CREATE INDEX IF NOT EXISTS book_creature_location_idx ON book_creature (creature_location_id);
